                      "milliliters", "l", "liter", "liters", "pinch", "pinches", "dash", 
                      "dashes", "clove", "cloves", "bunch", "bunches", "sprig", "sprigs"]

        for ingredient in ingredients:
            quantity = ingredient.get("quantity", "")

            # Check if quantity follows the required format: number + space + unit
            # Fractions must use slash format (e.g., "1/2" not "0.5")
            import re
            quantity_pattern = r'^(\d+(?:\/\d+)?) ([a-zA-Z]+)$'
