            # Validate that the unit is from the approved list
            unit = match.group(2).lower()
            if unit not in valid_units:
                return json.dumps({
                    "success": False,
                    "message": f"Invalid unit '{unit}' for ingredient '{ingredient.get('name')}'. Must be one of the standard culinary units."
                })
        ### End of modification ###

